using System;
using System.Net;
using System.IO;
using System.Text;

public static class Snippet
{
	public static void Getholiday(System.String Year)
    {
        FetchAndSaveHolidays(Year); // 引数として渡す
    }

    private static void FetchAndSaveHolidays(string year)
    {
        string countryCode = "JP";
        string url = "https://date.nager.at/api/v3/PublicHolidays/" + year + "/" + countryCode;

        WebClient client = new WebClient();
        string json = client.DownloadString(url);

        string path = "E:\\holidays.csv";

        Encoding sjis = Encoding.GetEncoding(932, new EncoderReplacementFallback("?"), new DecoderReplacementFallback("?"));

        using (StreamWriter writer = new StreamWriter(path, false, sjis))
        {
            string header = string.Concat("D", "a", "t", "e", ",", "L", "o", "c", "a", "l", "N", "a", "m", "e", ",", "E", "n", "g", "l", "i", "s", "h", "N", "a", "m", "e");
            writer.WriteLine(header);

            string[] items = json.Split(new string[] { "{" }, StringSplitOptions.RemoveEmptyEntries);

            for (int i = 0; i < items.Length; i++)
            {
                string item = items[i];
                string line = item.Replace("}", "").Replace("[", "").Replace("]", "").Replace("\"", "").Trim();

                string date = ExtractValue(line, "date:");
                string localName = ExtractValue(line, "localName:");
                string name = ExtractValue(line, "name:");

                if (date != "" && localName != "" && name != "")
                {
                    writer.WriteLine(date + "," + localName + "," + name);
                }
            }
        }
    }

    private static string ExtractValue(string source, string key)
    {
        int index = source.IndexOf(key);
        if (index >= 0)
        {
            int start = index + key.Length;
            int end = source.IndexOf(",", start);
            if (end == -1)
            {
                end = source.Length;
            }
            return source.Substring(start, end - start).Trim();
        }
        return "";
    }
}

