using System;
using System.Net;
using System.IO;
using System.Text;
using System.Web.Script.Serialization;
using System.Collections.Generic;

public static class Snippet
{
	public static void Getholiday(System.String Year)
    {
        FetchAndSaveHolidays(Year);
    }

    private static void FetchAndSaveHolidays(string year)
    {
        string countryCode = "JP";
        string url = "https://date.nager.at/api/v3/PublicHolidays/" + year + "/" + countryCode;

        WebClient client = new WebClient();
        string json = client.DownloadString(url);

        // JSON → オブジェクト
        JavaScriptSerializer serializer = new JavaScriptSerializer();
        List<Holiday> holidays = serializer.Deserialize<List<Holiday>>(json);

        // 書き込み先（UTF-8 BOMなし）
        string path = "E:\\holidays.csv";
        Encoding utf8NoBom = new UTF8Encoding(false); // false = BOMなし

        using (StreamWriter writer = new StreamWriter(path, false, utf8NoBom))
        {
            writer.WriteLine("Date,LocalName,EnglishName");

            foreach (Holiday h in holidays)
            {
                writer.WriteLine(h.date + "," + h.localName + "," + h.name);
            }
        }
    }

    private class Holiday
    {
        public string date { get; set; }
        public string localName { get; set; }
        public string name { get; set; }
    }
}
